/*
PLAN
1) Composition: backdrop gradient plane 7x6 at z=-2.5; parallax photo plate 4.0x2.5 centered slightly right/up; bottom scrim over plate; caption block (kicker/headline/accent bar/body/caption) anchored bottom-left of plate at z=0.35; contact glow foreground accent.
2) Light rig: rig-dusk-editorial — warm key #ffc890 2.8, fill point #b9a68e 3.0, rim #f2f4f6 1.7, ambient floor 0.09; node-local.
3) Materials: plate = MeshStandardNodeMaterial with TSL depth displacement (amp 0.18), filmic grade (lifted blacks #0d0d12, shouldered highlights, +12% midtone contrast, -8% desat with red preserved), depth-edge rim light; scrim + backdrop = basic node gradients.
4) Motion: plate opacity 0->1 500ms power2.out; caption rise-in y+0.4 700ms power3.out delayed 120ms; idle single slow breathing <=1.5%; parallax-scroll primitive intensity 0.35.
5) Focal element: the depth-separated photo subject with warm key rim — single brightest read; headline paper-white second; accent red hairline used exactly once.
*/
import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  uv, vec2, vec3, vec4, float, mix, smoothstep, clamp, texture, uniform,
  positionLocal, dot, pow, max, abs, sub, add, mul, oneMinus
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group, Mesh, PlaneGeometry, CircleGeometry, DirectionalLight, PointLight,
    AmbientLight, Color, Texture
  } = ctx.THREE;

  const colors = config.intent?.visualSpec?.colors ?? {};
  const C_BG = colors.background ?? '#0b0b10';       // color.background
  const C_SURFACE = colors.surface ?? '#16161d';     // color.surface
  const C_INK = colors.ink ?? '#16161d';             // color.ink
  const C_PAPER = colors.paper ?? '#e8ecf2';         // color.paper
  const C_ACCENT = colors.accent ?? '#ff2a38';       // color.accent

  const group = new Group();
  group.name = 'photo-hero-composite';

  const disposables = [];
  const timelines = [];
  const primHandles = [];

  // ---------- backdropStage: gradient stage plane (color.gradient) ----------
  const bgGeo = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  {
    const t = uv().y; // 0 bottom -> 1 top
    const cBase = vec3(...new Color(C_BG).toArray());
    const cSurf = vec3(...new Color(C_SURFACE).toArray());
    // engineered vertical gradient: surface glow upper-mid falling to near-black base
    const g = smoothstep(0.05, 0.85, t);
    const vign = smoothstep(1.0, 0.35, abs(uv().x.sub(0.5)).mul(2.0));
    bgMat.colorNode = mix(cBase, cSurf.mul(1.35), g.mul(0.8).mul(vign).add(0.08));
  }
  const backdrop = new Mesh(bgGeo, bgMat);
  backdrop.position.set(0, -0.25, -2.5);
  group.add(backdrop);
  disposables.push(bgGeo, bgMat);

  // ---------- lightRig: rig-dusk-editorial ----------
  const R = 1.6; // subject bounding radius
  const key = new DirectionalLight(new Color('#ffc890'), 2.8);
  key.position.set(3 * R, 0.9 * R, 1.2 * R);
  key.target.position.set(0, 0.4, 0);
  const fill = new PointLight(new Color('#b9a68e'), 3.0, 9, 2);
  fill.position.set(-2.4 * R, 0.6 * R, 1.8 * R);
  const rim = new DirectionalLight(new Color('#f2f4f6'), 1.5);
  rim.position.set(-1.8 * R, 2.8 * R, -2 * R);
  rim.target.position.set(0, 0.6, 0);
  const amb = new AmbientLight(new Color(C_SURFACE), 0.09);
  group.add(key, key.target, fill, rim, rim.target, amb);

  // ---------- photoPlate: parallax-plane with depth displacement + filmic grade ----------
  const PLATE_W = 4.0, PLATE_H = 2.5;
  const plateGeo = new PlaneGeometry(PLATE_W, PLATE_H, 64, 64);
  const plateMat = new MeshStandardNodeMaterial();
  plateMat.roughness = 0.85;
  plateMat.metalness = 0.0;
  plateMat.transparent = true;

  const plateOpacity = uniform(0);
  const depthAmp = uniform(0.18);

  // Placeholder 1x1 textures replaced by loaders (cached, async-safe)
  const colorTexU = texture(new Texture());
  const depthTexU = texture(new Texture());
  let colorTexRef = null;
  let depthTexRef = null;

  // depth displacement along +z (effects.spec: amplitude 0.18)
  const d = depthTexU.sample(uv()).r;
  plateMat.positionNode = positionLocal.add(vec3(0.0, 0.0, d.mul(depthAmp)));

  // filmic grade
  {
    const src = colorTexU.sample(uv()).rgb;
    // highlights shouldered toward paper
    const paper = vec3(...new Color(C_PAPER).toArray());
    let c = mix(src, paper, smoothstep(0.75, 1.35, dot(src, vec3(0.299, 0.587, 0.114))).mul(0.35));
    // midtone contrast +12%
    c = clamp(c.sub(0.5).mul(1.12).add(0.5), 0.0, 1.0);
    // desaturate -8% but preserve red channel
    const luma = dot(c, vec3(0.299, 0.587, 0.114));
    const desat = mix(c, vec3(luma), 0.08);
    c = vec3(c.r, desat.g, desat.b);
    // blacks lifted to #0d0d12
    const lift = vec3(...new Color('#0d0d12').toArray());
    c = max(c, lift);
    // foreground subject rim: key-warm edge along depth silhouette (0.02-unit rim)
    const px = float(0.02 / PLATE_W);
    const dl = depthTexU.sample(uv().add(vec2(px.negate(), 0))).r;
    const dr = depthTexU.sample(uv().add(vec2(px, 0))).r;
    const du = depthTexU.sample(uv().add(vec2(0, px))).r;
    const dd = depthTexU.sample(uv().add(vec2(0, px.negate()))).r;
    const edge = clamp(abs(dl.sub(dr)).add(abs(du.sub(dd))).mul(6.0), 0.0, 1.0);
    const keyWarm = vec3(...new Color('#ffc890').toArray());
    plateMat.colorNode = c;
    plateMat.emissiveNode = keyWarm.mul(edge).mul(0.9);
  }
  plateMat.opacityNode = plateOpacity;

  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0.35, 0.15, 0);
  group.add(plate);
  disposables.push(plateGeo, plateMat);

  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    colorTexRef = tex;
    colorTexU.value = tex;
    plateMat.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
    depthTexRef = tex;
    depthTexU.value = tex;
    plateMat.needsUpdate = true;
  });

  // ---------- bottomScrim: gradient stops #0b0b1000 @0.45 -> #0b0b10eb @1.0 (color.gradient) ----------
  const scrimGeo = new PlaneGeometry(PLATE_W, PLATE_H);
  const scrimMat = new MeshBasicNodeMaterial();
  scrimMat.transparent = true;
  scrimMat.depthWrite = false;
  {
    const t = oneMinus(uv().y); // 0 top -> 1 bottom
    const a = smoothstep(0.45, 1.0, t).mul(0.92); // eb ≈ 0.92
    scrimMat.colorNode = vec3(...new Color(C_BG).toArray());
    scrimMat.opacityNode = a.mul(plateOpacity);
  }
  const scrim = new Mesh(scrimGeo, scrimMat);
  scrim.position.set(plate.position.x, plate.position.y, 0.22);
  group.add(scrim);
  disposables.push(scrimGeo, scrimMat);

  // ---------- captionBlock: kicker / headline / accent bar / body / caption ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = (role, fallback) =>
    items.find((i) => i.role === role)?.text ?? fallback;

  const caption = new Group();
  const PAD = 0.5, BASE = 0.25;
  const left = plate.position.x - PLATE_W / 2 + PAD;
  const bottom = plate.position.y - PLATE_H / 2 + PAD;

  const kickerText = ctx.fontAtlas.createText(byRole('kicker', 'NOVA ATELIER / GENEVA'), {
    fontSize: 9, color: C_PAPER, align: 'left', letterSpacingPx: 1.1
  });
  kickerText.position.set(0, BASE * 4.4, 0);
  caption.add(kickerText);

  const headlineText = ctx.fontAtlas.createText(byRole('headline', 'Time, Machined.'), {
    fontSize: 34, color: C_PAPER, align: 'left'
  });
  headlineText.position.set(0, BASE * 3.1, 0);
  caption.add(headlineText);

  // accentBar: 0.75w x 0.02h emissive hairline (color.accent)
  const barGeo = new PlaneGeometry(0.75, 0.02);
  const barMat = new MeshBasicNodeMaterial();
  barMat.colorNode = vec3(...new Color(C_ACCENT).toArray()).mul(1.8);
  const accentBar = new Mesh(barGeo, barMat);
  accentBar.position.set(0.375, BASE * 2.2, 0);
  caption.add(accentBar);
  disposables.push(barGeo, barMat);

  const bodyText = ctx.fontAtlas.createText(
    byRole('body', 'Every case begins as a single billet of 904L steel.'),
    { fontSize: 13, color: C_PAPER, align: 'left', maxWidthPx: 420 }
  );
  bodyText.position.set(0, BASE * 1.3, 0);
  caption.add(bodyText);

  const captionText = ctx.fontAtlas.createText(byRole('caption', 'CALIBRE NA-01 / 72 HOUR RESERVE'), {
    fontSize: 9, color: '#9aa2ad', align: 'left', letterSpacingPx: 1.1
  });
  captionText.position.set(0, 0, 0);
  caption.add(captionText);

  caption.position.set(left, bottom, 0.35);
  group.add(caption);

  // ---------- contactGlow: foreground accent depth plane ----------
  const glowGeo = new CircleGeometry(2.4, 48);
  const glowMat = new MeshBasicNodeMaterial();
  glowMat.transparent = true;
  glowMat.depthWrite = false;
  {
    const r = uv().sub(vec2(0.5, 0.5)).length().mul(2.0);
    glowMat.colorNode = vec3(...new Color(C_SURFACE).toArray()).mul(1.4);
    glowMat.opacityNode = smoothstep(1.0, 0.0, r).mul(0.35);
  }
  const glow = new Mesh(glowGeo, glowMat);
  glow.position.set(0.35, -1.35, -1.2);
  glow.rotation.x = 0;
  group.add(glow);
  disposables.push(glowGeo, glowMat);

  // ---------- entranceMotion ----------
  const tl = gsap.timeline();
  tl.to(plateOpacity, { value: 1, duration: 0.5, ease: 'power2.out' }, 0);
  caption.position.y = bottom - 0.4;
  const capMats = [];
  caption.traverse((o) => { if (o.material) capMats.push(o.material); });
  capMats.forEach((m) => { m.transparent = true; m.opacity = 0; });
  tl.to(caption.position, { y: bottom, duration: 0.7, ease: 'power3.out' }, 0.12);
  tl.to(capMats, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0.12);
  // weighted settle on plate scale, then ONE slow idle breathing <=1.5%
  tl.fromTo(plate.scale, { x: 1.04, y: 1.04 }, { x: 1, y: 1, duration: 0.9, ease: 'power4.out' }, 0);
  timelines.push(tl);
  const idle = gsap.to(plate.scale, {
    x: 1.012, y: 1.012, duration: 4.2, yoyo: true, repeat: -1, ease: 'sine.inOut', delay: 1.2
  });
  timelines.push(idle);

  // ---------- primitives: apply EVERY config.cinematicPrimitives entry ----------
  for (const prim of config.cinematicPrimitives ?? []) {
    const fn = ctx.primitives[prim.name];
    if (fn) primHandles.push(fn(plate, prim.params));
  }

  // ---------- handlers + cleanup ----------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    primHandles.forEach((h) => h?.cleanup?.());
    disposables.forEach((r) => r.dispose?.());
    if (colorTexRef) colorTexRef.dispose?.();
    if (depthTexRef) depthTexRef.dispose?.();
    caption.traverse((o) => {
      o.geometry?.dispose?.();
      o.material?.dispose?.();
    });
  };

  return group;
}

/* @spec-manifest
{"elements":[
{"id":"text.kicker.0","where":"captionBlock","how":"kickerText via ctx.fontAtlas.createText"},
{"id":"text.headline.1","where":"captionBlock","how":"headlineText via ctx.fontAtlas.createText"},
{"id":"text.body.2","where":"captionBlock","how":"bodyText via ctx.fontAtlas.createText"},
{"id":"text.caption.3","where":"captionBlock","how":"captionText via ctx.fontAtlas.createText"},
{"id":"color.background","where":"backdropStage","how":"C_BG base of stage gradient and scrim"},
{"id":"color.surface","where":"backdropStage","how":"C_SURFACE gradient top, glow, ambient"},
{"id":"color.ink","where":"createNode","how":"C_INK token bound as palette constant"},
{"id":"color.paper","where":"captionBlock","how":"paper text color and highlight shoulder"},
{"id":"color.accent","where":"captionBlock","how":"accentBar emissive hairline 0.75x0.02"},
{"id":"color.gradient","where":"bottomScrim","how":"0.45->1.0 alpha scrim gradient stops"},
{"id":"effects.spec","where":"photoPlate","how":"depth displacement, filmic grade, rim, scrim"},
{"id":"primitive.parallax-scroll","where":"primitives","how":"ctx.primitives loop applies parallax-scroll"}
]}
*/
